        // Delphi: function SplitDSMList(var List: string; var First: integer; var Last: integer): boolean
        public static bool SplitDSMList(ref string List, ref int First, ref int Last)
        {
            bool Result = false;
            int i = 0;
            bool ProcessingLast = false;
            Result = false;
            First = 0;
            Last = 0;
            ProcessingLast = false;
            {
                int __end1 = Rtl.Length(List); // Delphi evaluates the loop bound once
                for (i = 1; i <= __end1; i++)
                {
                    switch (List[i - 1])
                    {
                        case >= '0' and <= '9':
                            {
                                if (ProcessingLast)
                                {
                                    Last = Last * 10 + (int)List[i - 1] - 48;
                                    Result = true;
                                }
                                else
                                {
                                    First = First * 10 + (int)List[i - 1] - 48;
                                    Last = First;
                                    Result = true;
                                }
                            }
                            break;
                        case '-':
                            {
                                ProcessingLast = true;
                                Last = 0;
                                Result = true;
                            }
                            break;
                        case ',':
                            {
                                Result = true;
                                List = Rtl.Copy(List, i + 1, Rtl.Length(List) - i);
                                return Result;
                            }
                            break;
                        case ' ':
                            {
                            }
                            break;
                        default:
                            {
                                throw new EDSMListError("Illegal character found in list \"" + List + "\"");
                            }
                            break;
                    }
                }
            }
            List = "";
            return Result;
        }

        // Delphi: function ValueInDSMList(const List: string; const Val: integer): boolean
        public static bool ValueInDSMList(string List, int Val)
        {
            bool Result = false;
            string iList = "";
            int iBegin = 0;
            int iEnd = 0;
            iList = List;
            Result = false;
            while (SplitDSMList(ref iList, ref iBegin, ref iEnd))
            {
                if (Val < iBegin)
                {
                    return Result;
                }
                else if (Val <= iEnd)
                {
                    Result = true;
                    return Result;
                }
            }
            return Result;
        }

