        // Delphi: function ISQRT(const i: integer; const RoundUp: boolean): integer
        public static int ISQRT(int i, bool RoundUp)
        {
            int Result = 0;
            int iMin = 0;
            int iAve = 0;
            int iMax = 0;
            int iTest = 0;
            if (i < 0)
            {
                throw new Exception("Attempt to take SQRT of negative number (" + Rtl.IntToStr(i) + ")");
            }
            iMin = 0;
            iMax = i;
            while (true)
            {
                iAve = (iMin + iMax) / 2;
                iTest = iAve * iAve;
                if (iTest == i)
                {
                    Result = iAve;
                    return Result;
                }
                else if (iMin == iMax)
                {
                    Result = iMin;
                    return Result;
                }
                else if (iMax == iMin + 1)
                {
                    if (RoundUp)
                    {
                        Result = iMax;
                    }
                    else
                    {
                        Result = iMin;
                    }
                    return Result;
                }
                else if (iTest > i)
                {
                    iMax = iAve;
                }
                else
                {
                    iMin = iAve;
                }
            }
            return Result;
        }

        // Delphi: function ReplaceWord(const pText, pReplace, pReplaceBy: string; const pIgnoreCase, pWordsOnly: boolean): string
        public static string ReplaceWord(string pText, string pReplace, string pReplaceBy, bool pIgnoreCase, bool pWordsOnly)
        {
            string Result = "";
            int i = 0;
            bool iCanBeWord = false;
            bool iMatch = false;
            int iReplaceLen = 0;
            int iReplaceByLen = 0;
            int iTotalLen = 0;
            Result = "";
            iCanBeWord = true;
            iReplaceLen = Rtl.Length(pReplace);
            iReplaceByLen = Rtl.Length(pReplaceBy);
            iTotalLen = Rtl.Length(pText);
            Result = pText;
            if (iReplaceLen == 0)
            {
                return Result;
            }
            i = 0;
            while (i < iTotalLen)
            {
                i++;
                if (pIgnoreCase)
                {
                    iMatch = Rtl.SameText(Rtl.Copy(Result, i, iReplaceLen), pReplace);
                }
                else
                {
                    iMatch = Rtl.Copy(Result, i, iReplaceLen) == pReplace;
                }
                if (iMatch)
                {
                    if (pWordsOnly)
                    {
                        if (!iCanBeWord)
                        {
                            iMatch = false;
                        }
                        else if (i + iReplaceLen <= iTotalLen)
                        {
                            iMatch = !CouldBeWordChar(Result[i + iReplaceLen - 1]);
                        }
                    }
                }
                if (iMatch)
                {
                    Result = Rtl.Copy(Result, 1, i - 1) + pReplaceBy + Rtl.Copy(Result, i + iReplaceLen, iTotalLen);
                    i = i + iReplaceByLen - 1;
                    iTotalLen = Rtl.Length(Result);
                    iCanBeWord = false;
                }
                else
                {
                    iCanBeWord = !CouldBeWordChar(Result[i - 1]);
                }
            }
            return Result;
        }

        // Delphi: function TextSimilar(const pString1, pString2: string; const MinMatchPC, MaxLenDiff: integer): boolean
        public static bool TextSimilar(string pString1, string pString2, int MinMatchPC, int MaxLenDiff)
        {
            bool Result = false;
            int i = 0;
            int iMinLength = 0;
            int iMatchCount = 0;
            int iLen1 = 0;
            int iLen2 = 0;
            int iDiff = 0;
            iMinLength = (MinMatchPC + 99) / 100;
            if (Rtl.Length(pString1) < iMinLength)
            {
                Result = Rtl.SameText(pString1, pString2);
            }
            else
            {
                iMatchCount = 0;
                iLen1 = Rtl.Length(pString1);
                iLen2 = Rtl.Length(pString2);
                if (iLen1 > iLen2)
                {
                    iDiff = iLen1 - iLen2;
                }
                else
                {
                    iDiff = iLen2 - iLen1;
                }
                if (iDiff > MaxLenDiff)
                {
                    Result = false;
                    return Result;
                }
                for (i = 1; i <= iLen1; i++)
                {
                    if (Rtl.SameText(pString1[i - 1].ToString(), pString2[i - 1].ToString()))
                    {
                        iMatchCount++;
                    }
                    else
                    {
                        break;
                    }
                }
                for (i = iLen1; i >= iMatchCount + 1; i--)
                {
                    if (Rtl.SameText(pString1[i - 1].ToString(), pString2[i - 1].ToString()))
                    {
                        iMatchCount++;
                    }
                    else
                    {
                        break;
                    }
                }
                Result = iMatchCount >= iMinLength;
            }
            return Result;
        }

        // Delphi: function CouldBeWordChar(pVal: char): boolean
        internal static bool CouldBeWordChar(char pVal)
        {
            bool Result = false;
            switch (pVal)
            {
                case (>= 'a' and <= 'z') or (>= 'A' and <= 'Z') or (>= '0' and <= '9') or '_':
                    {
                        Result = true;
                    }
                    break;
                default:
                    {
                        Result = false;
                    }
                    break;
            }
            return Result;
        }

